def countSameProductTuples(nums):
    n = len(nums)
    cnt = {}
    for i in range(n):
        a = nums[i]
        for j in range(i + 1, n):
            p = a * nums[j]
            cnt[p] = cnt.get(p, 0) + 1
    total = 0
    for f in cnt.values():
        total += f * (f - 1) // 2
    return 8 * total
